```c
/*
 * Tree files: store an export as a tree of small block files rather
 * than one large file.
 *
 * Each block file holds TREEPAGESIZE bytes; every directory holds at
 * most TREEDIRSIZE entries (subdirectories, or block files at the
 * bottom level). The nesting depth depends on the size of the export.
 * Directories are named TREEXXXX, block files FILEXXXX, where XXXX is
 * the index of the entry in its parent directory, in hex.
 */

#include "lfs.h"

#include "treefiles.h"

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>

/**
 * Compute the number of directory levels needed below the tree root to
 * hold an export of the given size.
 *
 * @param size the size of the export, in bytes
 * @return the number of levels of subdirectories; 0 if all block files
 * fit in the root directory of the tree
 **/
static int tree_depth(off_t size) {
	int depth = 0;
	off_t nblocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	unsigned long long capacity = TREEDIRSIZE;

	while (capacity < (unsigned long long)nblocks) {
		capacity *= TREEDIRSIZE;
		depth++;
	}

	return depth;
}

void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int depth = tree_depth(size);
	off_t block = pos / TREEPAGESIZE;
	off_t divisor = 1;
	int i;
	int used = strlen(name);

	for (i = 0; i < depth; i++)
		divisor *= TREEDIRSIZE;

	*ppos = pos % TREEPAGESIZE;

	for (i = depth; i >= 1; i--) {
		used += snprintf(name + used, lenmax - used, "/TREE%04X",
				 (int)((block / divisor) % TREEDIRSIZE));
		divisor /= TREEDIRSIZE;
	}
	snprintf(name + used, lenmax - used, "/FILE%04X",
		 (int)(block % TREEDIRSIZE));
}
