		fd = open(path, mode);
	} else {
		pthread_mutex_lock(mutex);
		mkdir_path(path);
		fd = open(path, mode | O_CREAT, 0600);
		pthread_mutex_unlock(mutex);
	}
	free(path);

	return fd;
}
