/**
 * Read from a treefiles export. Data is stored in block files of
 * TREEPAGESIZE bytes, opened and closed on demand; missing blocks read
 * as zeroes.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an error
 **/
static ssize_t treeexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	off_t ppos = a % TREEPAGESIZE;
	int fhandle;
	size_t done = 0;

	if (len > (size_t)(TREEPAGESIZE - ppos))
		len = TREEPAGESIZE - ppos;

	fhandle = open_treefile(client->exportname, O_RDONLY, client->exportsize, a, &client->treelock);
	if (fhandle < 0) {
		if (errno == ENOENT) {
			memset(buf, 0, len);
			return len;
		}
		return -1;
	}
	while (done < len) {
		ssize_t ret = pread(fhandle, buf + done, len - done, ppos + done);
		if (ret < 0) {
			if (errno == EINTR)
				continue;
			close(fhandle);
			return -1;
		}
		if (ret == 0)
			break;
		done += ret;
	}
	close(fhandle);
	/* reading past the end of a block file gives zeroes */
	memset(buf + done, 0, len - done);

	return len;
}
```

