/**
 * Handle a TRIM request on a treefiles export. Block files that are
 * fully covered by the trim range are deleted; block files that are
 * only partially covered get a hole punched in them, if they exist.
 *
 * @param req the request for which this is being processed
 * @param client the client for which we're processing this request
 **/
static int tree_exptrim(struct nbd_request* req, CLIENT* client) {
	off_t from = req->from;
	off_t end = req->from + req->len;
	off_t blockstart = (from / TREEPAGESIZE) * TREEPAGESIZE;

	while(blockstart < end) {
		off_t blkend = blockstart + TREEPAGESIZE;

		if(blockstart >= from && blkend <= end) {
			pthread_mutex_lock(&client->treelock);
			delete_treefile(client->exportname,
					client->exportsize, blockstart);
			pthread_mutex_unlock(&client->treelock);
		} else {
			off_t start = from > blockstart ? from : blockstart;
			off_t stop = end < blkend ? end : blkend;
			int fhandle;

			/* only partially covered; just punch a hole */
			fhandle = open_treefile(client->exportname, O_RDWR,
					client->exportsize, blockstart,
					&client->treelock);
			if(fhandle >= 0) {
				punch_hole(fhandle, start - blockstart,
						stop - start);
				close(fhandle);
			} else if(errno != ENOENT) {
				return -1;
			}
		}
		blockstart = blkend;
	}
	DEBUG("Performed TRIM request from %llu to %llu", (unsigned long long) req->from, (unsigned long long) req->len);
	return 0;
}
```

