/*
 * Tree files support.
 *
 * An export is stored as a tree of small block files rather than as
 * one large file. Every block file holds TREEPAGESIZE bytes of data,
 * and every directory holds at most TREEDIRSIZE entries (either
 * subdirectories, or block files at the bottom level). The number of
 * levels of subdirectories needed therefore depends on the size of
 * the export.
 *
 * Subdirectories are named TREEXXXX, block files are named FILEXXXX,
 * where XXXX is the index (in hexadecimal) of the entry in its parent
 * directory. The root of the tree is the exportname itself, which is
 * a directory.
 */

#include "lfs.h"

#include "treefiles.h"

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>

/**
 * Calculate the number of levels of subdirectories needed below the
 * root of the tree to hold an export of the given size.
 *
 * @param size the size of the export, in bytes
 * @return the number of levels of subdirectories, or 0 if all block
 * files fit in the root directory of the tree
 **/
static int tree_depth(off_t size) {
	int depth = 0;
	off_t nblocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	unsigned long long capacity = TREEDIRSIZE;

	while (capacity < (unsigned long long)nblocks) {
		capacity *= TREEDIRSIZE;
		depth++;
	}

	return depth;
}

/**
 * Number of characters needed by construct_path() on top of the
 * length of the name of the root of the tree. Every level adds at
 * most "/TREEXXXX" (9 characters), the block file adds "/FILEXXXX".
 */
#define TREEPATH_EXTRA(depth) (((depth) + 1) * 10 + 1)

void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int depth = tree_depth(size);
	off_t block = pos / TREEPAGESIZE;
	off_t divisor = 1;
	int used = strlen(name);
	int i;

	*ppos = pos % TREEPAGESIZE;

	for(i = 0; i < depth; i++) {
		divisor *= TREEDIRSIZE;
	}

	for(i = depth; i >= 1; i--) {
		int remain = lenmax - used;

		if(remain <= 0) {
			return;
		}
		used += snprintf(name + used, remain, "/TREE%04X",
				(int)((block / divisor) % TREEDIRSIZE));
		divisor /= TREEDIRSIZE;
	}
	if(lenmax - used > 0) {
		snprintf(name + used, lenmax - used, "/FILE%04X",
				(int)(block % TREEDIRSIZE));
	}
}

void mkdir_path(char *path) {
	char *p = path;

	if(*p == '/') {
		p++;
	}
	while((p = strchr(p, '/')) != NULL) {
		*p = '\0';
		/* if this fails, open() will fail later on */
		mkdir(path, 0700);
		*p = '/';
		p++;
	}
}

int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	int depth = tree_depth(size);
	int len = strlen(name) + TREEPATH_EXTRA(depth);
	char *path = malloc(len);
	int fd;
	off_t ppos;

	if(path == NULL) {
		return -1;
	}
	strcpy(path, name);
	construct_path(path, len, size, pos, &ppos);

	if((mode & O_ACCMODE) == O_RDONLY) {
		fd = open(path, mode);
	} else {
		pthread_mutex_lock(mutex);
		if(mode & O_CREAT) {
			mkdir_path(path);
		}
		fd = open(path, mode, 0600);
		pthread_mutex_unlock(mutex);
	}
	free(path);

	return fd;
}

void delete_treefile(char *name, off_t size, off_t pos) {
	int depth = tree_depth(size);
	int len = strlen(name) + TREEPATH_EXTRA(depth);
	char *path = malloc(len);
	char *sep;
	off_t ppos;

	if(path == NULL) {
		return;
	}
	strcpy(path, name);
	construct_path(path, len, size, pos, &ppos);

	if(unlink(path) == 0 && depth > 0) {
		/* also remove the parent directory, if it is empty
		 * now; the root of the tree is never removed */
		sep = strrchr(path, '/');
		if(sep != NULL && sep != path) {
			*sep = '\0';
			rmdir(path);
		}
	}
	free(path);
}

