	int fd;
	int i;
	SERVER srv;
	CLIENT cl;
	struct nbd_request req;

	/* path construction; 1024 blocks fit directly in the root */
	strcpy(path, "/tree");
	construct_path(path, sizeof(path), (off_t)4096 * 1024, 0, &ppos);
	count_assert(strcmp(path, "/tree/FILE0000") == 0);
	count_assert(ppos == 0);

	strcpy(path, "/tree");
	construct_path(path, sizeof(path), (off_t)4096 * 1024,
			(off_t)4096 * 1024 - 1, &ppos);
	count_assert(strcmp(path, "/tree/FILE03FF") == 0);
	count_assert(ppos == 4095);

	/* 1025 blocks need one level of subdirectories */
	strcpy(path, "/tree");
	construct_path(path, sizeof(path), (off_t)4096 * 1025,
			(off_t)4096 * 100 + 5, &ppos);
	count_assert(strcmp(path, "/tree/TREE0000/FILE0064") == 0);
	count_assert(ppos == 5);

	strcpy(path, "/tree");
	construct_path(path, sizeof(path), (off_t)4096 * 1025,
			(off_t)4096 * 1024, &ppos);
	count_assert(strcmp(path, "/tree/TREE0001/FILE0000") == 0);
	count_assert(ppos == 0);

	/* 1024*1024+1 blocks need two levels of subdirectories */
	strcpy(path, "/tree");
	construct_path(path, sizeof(path),
			(off_t)4096 * 1024 * 1024 + 4096,
			(off_t)4096 * 1024 * 1024, &ppos);
	count_assert(strcmp(path, "/tree/TREE0001/TREE0000/FILE0000") == 0);
	count_assert(ppos == 0);

	count_assert(mkdtemp(root1) != NULL);

	/* open for writing creates directories and file on demand */
	fd = open_treefile(root1, O_RDWR | O_CREAT, (off_t)4096 * 1024,
			(off_t)4096 * 5 + 10, &mutex);
	count_assert(fd >= 0);
	count_assert(pwrite(fd, "hello", 5, 10) == 5);
	close(fd);
	count_assert(file_exists(root1, "FILE0005"));

	/* the data can be read back through the tree */
	fd = open_treefile(root1, O_RDONLY, (off_t)4096 * 1024,
			(off_t)4096 * 5, &mutex);
	count_assert(fd >= 0);
	memset(buf, 0, sizeof(buf));
	count_assert(pread(fd, buf, 15, 0) == 15);
	count_assert(memcmp(buf + 10, "hello", 5) == 0);
	close(fd);

	/* opening a block that was never written fails with ENOENT,
	 * both for reading and for writing without O_CREAT */
	errno = 0;
	fd = open_treefile(root1, O_RDONLY, (off_t)4096 * 1024,
			(off_t)4096 * 6, &mutex);
	count_assert(fd == -1 && errno == ENOENT);
	errno = 0;
	fd = open_treefile(root1, O_RDWR, (off_t)4096 * 1024,
			(off_t)4096 * 6, &mutex);
	count_assert(fd == -1 && errno == ENOENT);

	/* deleting a block removes its file */
	delete_treefile(root1, (off_t)4096 * 1024, (off_t)4096 * 5);
	count_assert(!file_exists(root1, "FILE0005"));

	count_assert(mkdtemp(root2) != NULL);

	/* TRIM over the whole export deletes all block files */
	memset(&srv, 0, sizeof(srv));
	memset(&cl, 0, sizeof(cl));
	srv.flags = F_TREEFILES;
	srv.expected_size = (off_t)4096 * 4;
	cl.exportsize = (off_t)4096 * 4;
	cl.exportname = root2;
	cl.server = &srv;
	pthread_mutex_init(&cl.treelock, NULL);

	for(i = 0; i < 3; i++) {
		fd = open_treefile(root2, O_RDWR | O_CREAT,
				(off_t)4096 * 4, (off_t)4096 * i,
				&cl.treelock);
		count_assert(fd >= 0);
		count_assert(pwrite(fd, "data", 4, 0) == 4);
		close(fd);
	}
	count_assert(file_exists(root2, "FILE0000"));
	count_assert(file_exists(root2, "FILE0001"));
	count_assert(file_exists(root2, "FILE0002"));

	req.magic = NBD_REQUEST_MAGIC;
	req.type = NBD_CMD_TRIM;
	req.from = 0;
	req.len = (off_t)4096 * 4;
	count_assert(exptrim(&req, &cl) == 0);
	count_assert(!file_exists(root2, "FILE0000"));
	count_assert(!file_exists(root2, "FILE0001"));
	count_assert(!file_exists(root2, "FILE0002"));

	/* TRIM covering a block only partially keeps the file and
	 * punches a hole in it instead */
	for(i = 0; i < 4; i++) {
		fd = open_treefile(root2, O_RDWR | O_CREAT,
				(off_t)4096 * 4, (off_t)4096 * i,
				&cl.treelock);
		count_assert(fd >= 0);
		count_assert(pwrite(fd, "data", 4, 0) == 4);
		close(fd);
	}
	g_fd = -1;
	g_off = -1;
	g_len = -1;
	req.from = 100;
	req.len = (off_t)4096 * 2 + 100;
	count_assert(exptrim(&req, &cl) == 0);
	/* the range covers block 0 partially, block 1 fully and
	 * block 2 partially; block 3 is not touched at all */
	count_assert(file_exists(root2, "FILE0000"));
	count_assert(!file_exists(root2, "FILE0001"));
	count_assert(file_exists(root2, "FILE0002"));
	count_assert(file_exists(root2, "FILE0003"));
	/* last hole punched was in FILE0002: 200 bytes at offset 0 */
	count_assert(g_fd >= 0);
	count_assert(g_off == 0);
	count_assert(g_len == 200);

	snprintf(cmd, sizeof(cmd), "rm -rf %s %s", root1, root2);
	count_assert(system(cmd) == 0);

	return 0;
}
